\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
tick label style={font=\footnotesize},
        label style={font=\small},
        legend style={font=\footnotesize},
        tick style={line width=0.8pt, color=black},
        axis line style = thick,
        axis y line = center,
        axis x line = middle,
        %axis equal,
        %grid = both,
        xmin = -6.0,
        xmax = 5.0,
        ymin = -17.5,
        ymax = 2.5,
        xtick = {-3,4},
        ytick = {-12},
        xlabel style={below right},
		ylabel style={above right},
		%% Here, we can control the positioning of each individual tick.
		x tick label style={xshift={(\tick==4)*3pt}},
               x tick label style={xshift={(\tick==-3)*-2pt}},
		y tick label style={yshift={(\tick==-12)*0pt}},
		every axis x label/.style={
			at={(ticklabel* cs:1.02)},
			anchor=west,
		},
		every axis y label/.style={
			at={(ticklabel* cs:1.02)},
			anchor=south,
		}
]

% Graphic
\addplot [domain=-6:5,samples=200,color=red,line width=1pt]{1/3*(x-4)*(x+3)^2};

\end{axis}

\end{tikzpicture}
\end{document}

